package dialects_test

import (
	"testing"

	"github.com/pressly/goose/v3/internal/dialects"
	"github.com/stretchr/testify/require"
)

// TestTableExistsSQL verifies the SQL generated by each dialect's TableExists implementation.
// These are unit tests — no database connection is required.
func TestTableExistsSQL(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name      string
		querier   interface{ TableExists(string) string }
		tableName string
		wantSQL   string
	}{
		// Postgres — plain table uses current_schema()
		{
			name:      "postgres/plain",
			querier:   dialects.NewPostgres().(interface{ TableExists(string) string }),
			tableName: "goose_db_version",
			wantSQL:   `SELECT EXISTS ( SELECT 1 FROM pg_tables WHERE (current_schema() IS NULL OR schemaname = current_schema()) AND tablename = 'goose_db_version' )`,
		},
		// Postgres — schema-qualified table
		{
			name:      "postgres/qualified",
			querier:   dialects.NewPostgres().(interface{ TableExists(string) string }),
			tableName: "public.goose_db_version",
			wantSQL:   `SELECT EXISTS ( SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'goose_db_version' )`,
		},
		// MySQL — plain table uses database()
		{
			name:      "mysql/plain",
			querier:   dialects.NewMysql().(interface{ TableExists(string) string }),
			tableName: "goose_db_version",
			wantSQL:   `SELECT EXISTS ( SELECT 1 FROM information_schema.tables WHERE (database() IS NULL OR table_schema = database()) AND table_name = 'goose_db_version' )`,
		},
		// MySQL — schema-qualified table
		{
			name:      "mysql/qualified",
			querier:   dialects.NewMysql().(interface{ TableExists(string) string }),
			tableName: "mydb.goose_db_version",
			wantSQL:   `SELECT EXISTS ( SELECT 1 FROM information_schema.tables WHERE table_schema = 'mydb' AND table_name = 'goose_db_version' )`,
		},
		// Aurora DSQL — same pg_tables query as Postgres
		{
			name:      "dsql/plain",
			querier:   dialects.NewAuroraDSQL().(interface{ TableExists(string) string }),
			tableName: "goose_db_version",
			wantSQL:   `SELECT EXISTS ( SELECT 1 FROM pg_tables WHERE (current_schema() IS NULL OR schemaname = current_schema()) AND tablename = 'goose_db_version' )`,
		},
		{
			name:      "dsql/qualified",
			querier:   dialects.NewAuroraDSQL().(interface{ TableExists(string) string }),
			tableName: "public.goose_db_version",
			wantSQL:   `SELECT EXISTS ( SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'goose_db_version' )`,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := tc.querier.TableExists(tc.tableName)
			require.Equal(t, tc.wantSQL, got)
		})
	}
}

// TestTableExistsUnsupported verifies that dialects without a TableExists implementation do not
// satisfy the TableExists interface, ensuring they fall back to ErrUnsupported at runtime.
func TestTableExistsUnsupported(t *testing.T) {
	t.Parallel()

	unsupported := []struct {
		name    string
		querier interface{}
	}{
		{"clickhouse", dialects.NewClickhouse()},
		{"mssql", dialects.NewSqlserver()},
		{"spanner", dialects.NewSpanner()},
		{"sqlite3", dialects.NewSqlite3()},
		{"turso", dialects.NewTurso()},
		{"vertica", dialects.NewVertica()},
		{"ydb", dialects.NewYDB()},
		{"redshift", dialects.NewRedshift()},
		{"tidb", dialects.NewTidb()},
		{"starrocks", dialects.NewStarrocks()},
	}

	for _, tc := range unsupported {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			_, ok := tc.querier.(interface{ TableExists(string) string })
			require.False(t, ok, "dialect %q should not implement TableExists", tc.name)
		})
	}
}
